function Resolve-DefaultBookmarksFile {
    param(
        [Parameter(Mandatory = $true)]
        [string]$BrowserName
    )

    $localAppData = [Environment]::GetFolderPath("LocalApplicationData")

    switch ($BrowserName.ToLowerInvariant()) {
        "cent" {
            return Join-Path $localAppData "CentBrowser\User Data\Default\Bookmarks"
        }
        "edge" {
            return Join-Path $localAppData "Microsoft\Edge\User Data\Default\Bookmarks"
        }
        "chrome" {
            return Join-Path $localAppData "Google\Chrome\User Data\Default\Bookmarks"
        }
        default {
            throw "Unsupported browser: $BrowserName. Use Auto, Cent, Edge, Chrome, or pass -BookmarksFile explicitly."
        }
    }
}

function Resolve-BookmarksFileAuto {
    $localAppData = [Environment]::GetFolderPath("LocalApplicationData")
    $candidates = @(
        (Join-Path $localAppData "CentBrowser\User Data\Default\Bookmarks"),
        (Join-Path $localAppData "Microsoft\Edge\User Data\Default\Bookmarks"),
        (Join-Path $localAppData "Google\Chrome\User Data\Default\Bookmarks")
    )

    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) {
            return $candidate
        }
    }

    throw "No default bookmarks file found for Cent Browser, Edge, or Chrome. Pass -BookmarksFile explicitly."
}

function Get-StandardBilibiliUrl {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Url
    )

    try {
        $uri = [System.Uri]$Url
    } catch {
        return $null
    }

    if ($uri.Host -ne "space.bilibili.com") {
        return $null
    }

    $path = $uri.AbsolutePath.TrimEnd("/")

    if ($path -match '^/(\d+)$') {
        return "https://space.bilibili.com/$($Matches[1])/upload/video"
    }

    if ($path -match '^/(\d+)/(video|upload/video)$') {
        return "https://space.bilibili.com/$($Matches[1])/upload/video"
    }

    return $null
}

function Clean-BookmarkTitle {
    param(
        [string]$Title,
        [string]$SuffixToTrim
    )

    if ([string]::IsNullOrWhiteSpace($Title)) {
        return $null
    }

    $cleanTitle = $Title.Trim()

    if (-not [string]::IsNullOrWhiteSpace($SuffixToTrim) -and $cleanTitle.EndsWith($SuffixToTrim)) {
        $cleanTitle = $cleanTitle.Substring(0, $cleanTitle.Length - $SuffixToTrim.Length).TrimEnd()
    }

    foreach ($marker in @("投稿视频", "的个人空间")) {
        $index = $cleanTitle.IndexOf($marker)
        if ($index -gt 0) {
            $cleanTitle = $cleanTitle.Substring(0, $index).Trim()
            break
        }
    }

    return $cleanTitle
}

