function Add-BookmarkMapEntry {
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Map,
        [string]$Url,
        [string]$Title,
        [string]$SuffixToTrim
    )

    if ([string]::IsNullOrWhiteSpace($Url)) {
        return
    }

    $standardUrl = Get-StandardBilibiliUrl -Url $Url
    if ($null -eq $standardUrl) {
        return
    }

    $cleanTitle = Clean-BookmarkTitle -Title $Title -SuffixToTrim $SuffixToTrim
    if ([string]::IsNullOrWhiteSpace($cleanTitle)) {
        return
    }

    if (-not $Map.ContainsKey($standardUrl)) {
        $Map[$standardUrl] = $cleanTitle
    }
}

function Read-BookmarksNode {
    param(
